def criar_papeis(apps, schema_editor):
    """Os papéis fixos de antes viram papéis editáveis; cada pessoa fica com o mesmo acesso que tinha."""
    Papel = apps.get_model('accounts', 'Papel')
    User = apps.get_model('accounts', 'User')
    for nome, descricao, role, acessos in PAPEIS:
        papel, _ = Papel.objects.get_or_create(nome=nome, defaults={'descricao': descricao, **acessos})
        roles = [role, 'vistoriador'] if role == 'tecnico' else [role]
        User.objects.filter(role__in=roles, papel__isnull=True).update(papel=papel)


